 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){if(Resources.Load<GameObject>("RiftGameplayHUD"))return;var go=new GameObject("ROM - Nertor combat HUD",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));DontDestroyOnLoad(go);go.AddComponent<NertorHUD>();}
 void Start(){var canvas=GetComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=125;var scaler=GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1920,1080);if(!W.Body)W.Body=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");panel=W.Panel(transform,"NertorHotbar",0,0,780,185);panel.anchorMin=panel.anchorMax=new Vector2(.5f,0);panel.pivot=new Vector2(.5f,0);panel.anchoredPosition=new Vector2(0,22);title=W.Label(panel,"",16,0,740,30,19,W.Gold);health=W.Label(panel,"",16,28,250,28,18);resource=W.Label(panel,"",270,28,470,28,18);var bg=W.Panel(panel,"Rage track",16,60,748,7);rage=W.Panel(bg,"Rage",0,0,748,7).GetComponent<Image>();rage.color=new Color(.8f,.12f,.2f);buttons=new Button[4];labels=new Text[4];for(int i=0;i<4;i++){int index=i;buttons[i]=W.Button(panel,"",16+i*190,78,178,55,()=>Current?.Request(index));labels[i]=buttons[i].GetComponentInChildren<Text>();labels[i].font=W.Body;labels[i].fontSize=16;}buff=W.Label(panel,"",16,138,748,26,17,W.Gold);target=W.Label(panel,"",16,-72,748,70,20);hint=W.Label(panel,"",16,164,748,25,15,W.Muted);}
