 void Update(){if(!panel)return;var c=Current;bool visible=c&&c.Prototype&&c.Actor&&c.Actor.Health.CurrentHealth>0&&!ClientFrontend.Pause&&!ClientFrontend.Hub;panel.gameObject.SetActive(visible);Legacy(c&&c.Prototype);if(!visible)return;double now=NetworkTime.time;title.text=c.Class.DisplayName+" · "+c.Actor.Health.CharacterName;health.text="VIDA "+c.Actor.Health.CurrentHealth+" / "+c.Actor.Health.MaxHealth;resource.text="FURIA "+Mathf.RoundToInt(c.Resource)+" / "+c.Class.MaximumResource;rage.rectTransform.localScale=new Vector3(c.Resource/c.Class.MaximumResource,1,1);string[] keys={"CLIC","F","Z","T"};for(int i=0;i<4;i++){var a=c.Definition(i);double remain=c.Ready.Count>i?c.Ready[i]-now:0;labels[i].text=keys[i]+" · "+a.DisplayName+"\n"+(remain>0?Mathf.CeilToInt((float)remain)+" s":a.Cost>c.Resource?"FALTA FURIA":"LISTO");buttons[i].interactable=remain<=0&&a.Cost<=c.Resource&&c.CastEnd<=now;}buff.text=c.BuffUntil>now?"RUGIDO · "+Mathf.CeilToInt((float)(c.BuffUntil-now))+" s":c.CastEnd>now?"EJECUTANDO · "+c.Definition(c.Casting)?.DisplayName:"";
 Health selected=null;float best=.8f;Vector3 forward=Quaternion.Euler(c.Actor.Input.LookX,c.Actor.Input.LookY,0)*Vector3.forward;foreach(var p in GameManager.Players){if(!p||!p.BOT||!p.MyCharacter||p.MyCharacter.Health.CurrentHealth<=0)continue;Vector3 delta=p.MyCharacter.transform.position-c.Actor.transform.position;if(delta.magnitude>35)continue;float score=Vector3.Dot(delta.normalized,forward);if(score>best){best=score;selected=p.MyCharacter.Health;}}target.text=selected?selected.CharacterName+" · "+selected.CurrentHealth+" / "+selected.MaxHealth:"";if(selected){var enemy=selected.GetComponent<RiftEnemyCombat>();if(enemy&&enemy.CastEnds>now)target.text+="\nPREPARANDO ATAQUE · "+(enemy.CastEnds-now).ToString("0.0")+" s";}
 nearby=null;foreach(var p in RiftPortal.All)if(p&&p.Definition&&Vector3.Distance(c.Actor.transform.position,p.transform.position)<p.Definition.InteractRange){nearby=p;break;}hint.text=nearby?"[E] "+nearby.Definition.DisplayName:"Clic: ataque básico · F: cleave · Z: impacto · T: rugido";if(nearby&&Input.GetKeyDown(KeyCode.E)&&UICursorManager.GamePlayInput())c.CmdPortal(nearby.Definition.Id);
 }
